CallPageNode.buildEventScript:

var okExist = false;
var defaultExist = false;

for (var idx in $e)
{
	if ($e[idx] == "ok")
		okExist = true;
	if ($e[idx] == "default")
		defaultExist = true;
}

if (okExist && defaultExist)
{
	return "ok 와 default 링크는 함께 사용할 수 없습니다.";
}
if (!okExist && !defaultExist)
{
	return "ok 와 default 링크중에 하나를 연결해야 합니다.";
}
return "";

